from pathlib import Path
p=Path('projects/05-tenantshield'); base='io/github/cheshmakzanoon/portfolio/tenantshield'
mods=['policy-core','policy-store','decision-service','demo-resource-server','verification']
def dep(a,g='io.github.cheshmakzanoon.portfolio',v=None,scope=None):
 return f'<dependency><groupId>{g}</groupId><artifactId>{a}</artifactId>'+ (f'<version>{v}</version>' if v else '')+(f'<scope>{scope}</scope>' if scope else '')+'</dependency>'
test=dep('junit-jupiter','org.junit',scope='test')+dep('assertj-core','org.assertj',scope='test')
D={'policy-core':test,'policy-store':dep('tenantshield-policy-core',v='${project.version}')+dep('postgresql','org.postgresql')+dep('HikariCP','com.zaxxer')+dep('flyway-core','org.flywaydb')+dep('flyway-database-postgresql','org.flywaydb')+test,'decision-service':dep('tenantshield-policy-store',v='${project.version}')+dep('spring-boot-starter-webmvc','org.springframework.boot')+dep('spring-boot-starter-oauth2-resource-server','org.springframework.boot')+dep('spring-boot-starter-actuator','org.springframework.boot')+dep('caffeine','com.github.ben-manes.caffeine')+test+dep('spring-boot-starter-test','org.springframework.boot',scope='test'),'demo-resource-server':dep('spring-boot-starter-webmvc','org.springframework.boot')+dep('spring-boot-starter-oauth2-resource-server','org.springframework.boot')+test,'verification':dep('tenantshield-decision-service',v='${project.version}')+test+dep('testcontainers-postgresql','org.testcontainers',scope='test')+dep('testcontainers','org.testcontainers',scope='test')+dep('spring-security-test','org.springframework.security',scope='test')}
(p/'pom.xml').write_text('<project xmlns="http://maven.apache.org/POM/4.0.0"><modelVersion>4.0.0</modelVersion><parent><groupId>io.github.cheshmakzanoon.portfolio</groupId><artifactId>java-portfolio</artifactId><version>1.0.0-SNAPSHOT</version><relativePath>../../pom.xml</relativePath></parent><artifactId>tenantshield</artifactId><packaging>pom</packaging><modules>'+''.join(f'<module>{m}</module>' for m in mods)+'</modules></project>')
for m in mods:
 q=p/m; (q/f'src/main/java/{base}').mkdir(parents=True,exist_ok=True); (q/f'src/test/java/{base}').mkdir(parents=True,exist_ok=True)
 plugin=''
 if m in ['decision-service','demo-resource-server']: plugin='<build><plugins><plugin><groupId>org.springframework.boot</groupId><artifactId>spring-boot-maven-plugin</artifactId><executions><execution><goals><goal>repackage</goal></goals><configuration><classifier>exec</classifier></configuration></execution></executions></plugin></plugins></build>'
 (q/'pom.xml').write_text(f'<project xmlns="http://maven.apache.org/POM/4.0.0"><modelVersion>4.0.0</modelVersion><parent><groupId>io.github.cheshmakzanoon.portfolio</groupId><artifactId>tenantshield</artifactId><version>1.0.0-SNAPSHOT</version></parent><artifactId>tenantshield-{m}</artifactId><dependencies>{D[m]}</dependencies>{plugin}</project>')
